import{_ as a,a0 as p,w as r,s as d,ao as l,I as o,a1 as i,A as n,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Hegemon：使用 Rust 编写的模块化系统监视程序 | LCTT x X-CMD","titleTemplate":false,"description":"Hegemon：使用 Rust 编写的模块化系统监视程序 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Hegemon：使用 Rust 编写的模块化系统监视程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Hegemon：使用 Rust 编写的模块化系统监视程序 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180925 Hegemon - A Modular System Monitor Application Written In Rust","title":"Hegemon：使用 Rust 编写的模块化系统监视程序","tag":"201810","desc":""},"relativePath":"201810/20180925 Hegemon - A Modular System Monitor Application Written In Rust.md","filePath":"[post].md"}'),u={name:"201810/20180925 Hegemon - A Modular System Monitor Application Written In Rust.md"};function g(m,t,h,b,k,f){const s=p("Link");return r(),d("div",null,[t[19]||(t[19]=l('<h1 id="hegemon-使用-rust-编写的模块化系统监视程序" tabindex="-1">Hegemon：使用 Rust 编写的模块化系统监视程序 <a class="header-anchor" href="#hegemon-使用-rust-编写的模块化系统监视程序" aria-label="Permalink to “Hegemon：使用 Rust 编写的模块化系统监视程序”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/hegemon-720x340.png" alt=""></p><p>在类 Unix 系统中监视运行进程时，最常用的程序是 <code>top</code> 和它的增强版 <code>htop</code>。我个人最喜欢的是 <code>htop</code>。但是，开发人员不时会发布这些程序的替代品。<code>top</code> 和 <code>htop</code> 工具的一个替代品是 <code>Hegemon</code>。它是使用 Rust 语言编写的模块化系统监视程序。</p><p>关于 Hegemon 的功能，我们可以列出以下这些：</p><ul><li>Hegemon 会监控 CPU、内存和交换页的使用情况。</li><li>它监控系统的温度和风扇速度。</li><li>更新间隔时间可以调整。默认值为 3 秒。</li><li>我们可以通过扩展数据流来展示更详细的图表和其他信息。</li><li>单元测试。</li><li>干净的界面。</li><li>自由开源。</li></ul><h3 id="安装-hegemon" tabindex="-1">安装 Hegemon <a class="header-anchor" href="#安装-hegemon" aria-label="Permalink to “安装 Hegemon”">​</a></h3><p>确保已安装 Rust 1.26 或更高版本。要在 Linux 发行版中安装 Rust，请参阅以下指南：</p>',7)),o("ul",null,[o("li",null,[i(s,{href:"https://www.ostechnix.com/install-rust-programming-language-in-linux/"},{default:n(()=>[...t[0]||(t[0]=[e("在 Linux 中安装 Rust 编程语言",-1)])]),_:1})])]),o("p",null,[t[2]||(t[2]=e("另外要安装 ",-1)),i(s,{href:"https://github.com/lm-sensors/lm-sensors"},{default:n(()=>[...t[1]||(t[1]=[e("libsensors",-1)])]),_:1}),t[3]||(t[3]=e(" 库。它在大多数 Linux 发行版的默认仓库中都有。例如，你可以使用以下命令将其安装在基于 RPM 的系统（如 Fedora）中：",-1))]),t[20]||(t[20]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install lm_sensors-devel</span></span></code></pre></div><p>在像 Ubuntu、Linux Mint 这样的基于 Debian 的系统上，可以使用这个命令安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install libsensors4-dev</span></span></code></pre></div><p>在安装 Rust 和 libsensors 后，使用命令安装 Hegemon：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cargo install hegemon</span></span></code></pre></div><p>安装 hegemon 后，使用以下命令开始监视 Linux 系统中正在运行的进程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hegemon</span></span></code></pre></div><p>以下是 Arch Linux 桌面的示例输出。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/Hegemon-in-action.gif" alt=""></p><p>要退出，请按 <code>Q</code>。</p><p>请注意，hegemon 仍处于早期开发阶段，并不能完全取代 <code>top</code> 命令。它可能存在 bug 和功能缺失。如果你遇到任何 bug，请在项目的 GitHub 页面中报告它们。开发人员计划在即将推出的版本中引入更多功能。所以，请关注这个项目。</p><p>就是这些了。希望这篇文章有用。还有更多的好东西。敬请关注！</p><p>干杯!</p><hr>',14)),o("p",null,[t[5]||(t[5]=e("via: ",-1)),i(s,{href:"https://www.ostechnix.com/hegemon-a-modular-system-monitor-application-written-in-rust/"},{default:n(()=>[...t[4]||(t[4]=[e("https://www.ostechnix.com/hegemon-a-modular-system-monitor-application-written-in-rust/",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("作者：",-1)),i(s,{href:"https://www.ostechnix.com/author/sk/"},{default:n(()=>[...t[6]||(t[6]=[e("SK",-1)])]),_:1}),t[11]||(t[11]=e(" 选题：",-1)),i(s,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[7]||(t[7]=[e("lujun9972",-1)])]),_:1}),t[12]||(t[12]=e(" 译者：",-1)),i(s,{href:"https://github.com/geekpi"},{default:n(()=>[...t[8]||(t[8]=[e("geekpi",-1)])]),_:1}),t[13]||(t[13]=e(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:n(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[16]||(t[16]=e("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:n(()=>[...t[15]||(t[15]=[e("Linux中国",-1)])]),_:1}),t[18]||(t[18]=e(" 荣誉推出",-1))])])}const c=a(u,[["render",g]]);export{C as __pageData,c as default};
